app.get("/api/sales/invoices",requireAuth,requirePermission("sales.view"),async(req,res,next)=>{try{const result=await pool.query(`SELECT i.id,i.invoice_number AS "invoiceNumber",i.invoice_date AS "invoiceDate",i.status,i.subtotal,i.tax_total AS "taxTotal",i.total,c.id AS "customerId",c.name AS "customerName",COALESCE((SELECT SUM(r.amount) FROM customer_receipts r WHERE r.company_id=i.company_id AND r.invoice_id=i.id),0) AS "amountPaid",COALESCE((SELECT SUM(sr.total) FROM sales_returns sr WHERE sr.company_id=i.company_id AND sr.invoice_id=i.id),0) AS "returnedAmount",EXISTS(SELECT 1 FROM sales_invoice_lines il WHERE il.company_id=i.company_id AND il.invoice_id=i.id AND il.quantity>COALESCE((SELECT SUM(rl.quantity) FROM sales_return_lines rl WHERE rl.company_id=il.company_id AND rl.invoice_line_id=il.id),0)) AS "hasReturnableLines",i.total-COALESCE((SELECT SUM(r.amount) FROM customer_receipts r WHERE r.company_id=i.company_id AND r.invoice_id=i.id),0)-COALESCE((SELECT SUM(sr.total) FROM sales_returns sr WHERE sr.company_id=i.company_id AND sr.invoice_id=i.id),0)-COALESCE((SELECT SUM(a.amount) FROM customer_credit_applications a WHERE a.company_id=i.company_id AND a.target_invoice_id=i.id),0)+COALESCE((SELECT SUM(a.amount) FROM customer_credit_applications a JOIN sales_returns sr ON sr.company_id=a.company_id AND sr.id=a.sales_return_id WHERE a.company_id=i.company_id AND sr.invoice_id=i.id),0)+COALESCE((SELECT SUM(f.amount) FROM customer_refunds f JOIN sales_returns sr ON sr.company_id=f.company_id AND sr.id=f.sales_return_id WHERE f.company_id=i.company_id AND sr.invoice_id=i.id),0) AS outstanding FROM sales_invoices i JOIN business_partners c ON c.company_id=i.company_id AND c.id=i.customer_id WHERE i.company_id=$1 GROUP BY i.id,c.id,c.name ORDER BY i.invoice_date DESC,i.created_at DESC LIMIT 250`,[req.auth!.companyId]);return res.json({invoices:result.rows});}catch(error){return next(error);}});

