app.get("/api/employee-advances",requireAuth,requirePermission("employees.advance.view"),async(req,res,next)=>{try{const q=await pool.query(`SELECT a.id,a.advance_number AS "advanceNumber",a.advance_date AS "advanceDate",a.amount,a.payment_method AS "paymentMethod",a.reference,a.notes,a.employee_id AS "employeeId",e.employee_number AS "employeeNumber",e.full_name AS "fullName",u.full_name AS "createdBy",je.entry_number AS "entryNumber" FROM employee_advances a JOIN employees e ON e.company_id=a.company_id AND e.id=a.employee_id JOIN users u ON u.company_id=a.company_id AND u.id=a.created_by LEFT JOIN journal_entries je ON je.company_id=a.company_id AND je.source_type='employee_advance' AND je.source_id=a.id WHERE a.company_id=$1 AND a.status='posted' ORDER BY a.advance_date DESC,a.created_at DESC LIMIT 500`,[req.auth!.companyId]);return res.json({advances:q.rows});}catch(e){return next(e);}});
app.post("/api/employee-advances",requireAuth,requirePermission("employees.advance.post"),async(req,res,next)=>{const p=advanceSchema.safeParse(req.body);if(!p.success)return res.status(400).json({error:{code:"VALIDATION_ERROR",message:"Check the employee, date, positive amount, payment method and reason."}});const x=p.data,cid=req.auth!.companyId,actor=req.auth!.userId,client=await pool.connect();try{await client.query("BEGIN");const employee=await client.query("SELECT id FROM employees WHERE company_id=$1 AND id=$2 AND active=true FOR UPDATE",[cid,x.employeeId]);if(!employee.rowCount)throw Object.assign(new Error("Choose an active employee."),{httpStatus:400});const amount=cents(x.amount),number=await nextDocumentNumber(client,cid,"employee_advance"),advance=await client.query<{id:string}>("INSERT INTO employee_advances(company_id,advance_number,employee_id,advance_date,amount,payment_method,reference,notes,created_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9) RETURNING id",[cid,number,x.employeeId,x.advanceDate,amount,x.paymentMethod,x.reference||null,x.notes,actor]);await writeJournal(client,{companyId:cid,actorId:actor,sourceType:"employee_advance",sourceId:advance.rows[0].id,description:`Employee advance ${number}`,effectiveDate:x.advanceDate,lines:[{accountCode:"1400",employeeId:x.employeeId,description:`Advance receivable ${number}`,debit:amount,credit:0},{accountCode:x.paymentMethod==="cash"?"1110":"1120",description:`Advance payment ${number}`,debit:0,credit:amount}]});await client.query("INSERT INTO audit_logs(company_id,actor_user_id,action,entity_type,entity_id,reason,after_data) VALUES($1,$2,'employee.advance.post','employee_advance',$3,$4,$5::jsonb)",[cid,actor,advance.rows[0].id,x.notes,JSON.stringify({...x,advanceNumber:number,amount})]);await client.query("COMMIT");return res.status(201).json({id:advance.rows[0].id,advanceNumber:number});}catch(e){await client.query("ROLLBACK").catch(()=>undefined);if((e as {httpStatus?:number}).httpStatus)return res.status(400).json({error:{code:"INVALID_REFERENCE",message:(e as Error).message}});return next(e);}finally{client.release();}});
const repaymentSchema=z.object({employeeId:z.string().uuid(),repaymentDate:z.string().date(),amount:z.coerce.number().min(.01).max(999999999999),paymentMethod:z.enum(["cash","upi","bank_transfer","cheque","other"]),reference:z.string().trim().max(160).optional().default(""),notes:z.string().trim().min(2).max(500)});
app.post("/api/employee-advance-repayments",requireAuth,requirePermission("employees.advance.repay"),async(req,res,next)=>{const p=repaymentSchema.safeParse(req.body);if(!p.success)return res.status(400).json({error:{code:"VALIDATION_ERROR",message:"Check the employee, date, positive amount, payment method and reason."}});const x=p.data,cid=req.auth!.companyId,actor=req.auth!.userId,client=await pool.connect();try{await client.query("BEGIN");const employee=await client.query("SELECT id FROM employees WHERE company_id=$1 AND id=$2 FOR UPDATE",[cid,x.employeeId]);if(!employee.rowCount)throw Object.assign(new Error("Choose an existing employee."),{httpStatus:400});const balance=await client.query<{amount:string}>("SELECT COALESCE(SUM(jl.debit-jl.credit),0)::text AS amount FROM journal_entry_lines jl JOIN accounts a ON a.company_id=jl.company_id AND a.id=jl.account_id JOIN journal_entries je ON je.company_id=jl.company_id AND je.id=jl.journal_entry_id WHERE jl.company_id=$1 AND jl.employee_id=$2 AND a.code='1400'",[cid,x.employeeId]);const amount=cents(x.amount),outstanding=cents(Number(balance.rows[0].amount));if(amount>outstanding)throw Object.assign(new Error("Repayment cannot exceed the employee's outstanding advance."),{httpStatus:409,errorCode:"EXCEEDS_BALANCE"});const number=await nextDocumentNumber(client,cid,"employee_advance_repayment"),repayment=await client.query<{id:string}>("INSERT INTO employee_advance_repayments(company_id,repayment_number,employee_id,repayment_date,amount,payment_method,reference,notes,created_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9) RETURNING id",[cid,number,x.employeeId,x.repaymentDate,amount,x.paymentMethod,x.reference||null,x.notes,actor]);await writeJournal(client,{companyId:cid,actorId:actor,sourceType:"employee_advance_repayment",sourceId:repayment.rows[0].id,description:`Employee advance repayment ${number}`,effectiveDate:x.repaymentDate,lines:[{accountCode:x.paymentMethod==="cash"?"1110":"1120",description:`Advance repayment received ${number}`,debit:amount,credit:0},{accountCode:"1400",employeeId:x.employeeId,description:`Employee advance recovered ${number}`,debit:0,credit:amount}]});await client.query("INSERT INTO audit_logs(company_id,actor_user_id,action,entity_type,entity_id,reason,after_data) VALUES($1,$2,'employee.advance.repay','employee_advance_repayment',$3,$4,$5::jsonb)",[cid,actor,repayment.rows[0].id,x.notes,JSON.stringify({...x,repaymentNumber:number,amount,outstandingBefore:outstanding,outstandingAfter:cents(outstanding-amount)})]);await client.query("COMMIT");return res.status(201).json({id:repayment.rows[0].id,repaymentNumber:number,outstanding:cents(outstanding-amount)});}catch(e){await client.query("ROLLBACK").catch(()=>undefined);const status=(e as {httpStatus?:number}).httpStatus;if(status)return res.status(status).json({error:{code:(e as {errorCode?:string}).errorCode??"INVALID_REFERENCE",message:(e as Error).message}});return next(e);}finally{client.release();}});const reportDates=z.object({from:z.string().date().optional(),to:z.string().date().optional()});
app.get("/api/accounting/trial-balance",requireAuth,requirePermission("accounting.view"),async(req,res,next)=>{const parsed=reportDates.safeParse(req.query);if(!parsed.success||(parsed.data.from&&parsed.data.to&&parsed.data.from>parsed.data.to))return res.status(400).json({error:{code:"INVALID_DATE_RANGE",message:"Check the report start and end dates."}});try{const q=await pool.query(`SELECT a.code,a.name,a.account_type AS "accountType",COALESCE(SUM(CASE WHEN je.id IS NOT NULL THEN jl.debit ELSE 0 END),0) AS debit,COALESCE(SUM(CASE WHEN je.id IS NOT NULL THEN jl.credit ELSE 0 END),0) AS credit FROM accounts a LEFT JOIN journal_entry_lines jl ON jl.company_id=a.company_id AND jl.account_id=a.id LEFT JOIN journal_entries je ON je.company_id=jl.company_id AND je.id=jl.journal_entry_id AND ($2::date IS NULL OR je.effective_date <= $2::date) WHERE a.company_id=$1 AND a.active=true GROUP BY a.id ORDER BY a.code`,[req.auth!.companyId,parsed.data.to??null]);const rows=q.rows.map(r=>({...r,debit:Number(r.debit),credit:Number(r.credit),balance:Number(r.accountType==="asset"||r.accountType==="expense"?r.debit-r.credit:r.credit-r.debit)}));return res.json({rows,totalDebit:rows.reduce((s,r)=>s+r.debit,0),totalCredit:rows.reduce((s,r)=>s+r.credit,0),to:parsed.data.to??null});}catch(e){return next(e);}});
app.get("/api/accounting/profit-loss",requireAuth,requirePermission("accounting.view"),async(req,res,next)=>{const parsed=reportDates.safeParse(req.query);if(!parsed.success||(parsed.data.from&&parsed.data.to&&parsed.data.from>parsed.data.to))return res.status(400).json({error:{code:"INVALID_DATE_RANGE",message:"Check the report start and end dates."}});try{const q=await pool.query(`SELECT a.code,a.name,a.account_type AS "accountType",COALESCE(SUM(jl.debit),0) AS debit,COALESCE(SUM(jl.credit),0) AS credit FROM accounts a JOIN journal_entry_lines jl ON jl.company_id=a.company_id AND jl.account_id=a.id JOIN journal_entries je ON je.company_id=jl.company_id AND je.id=jl.journal_entry_id WHERE a.company_id=$1 AND a.active=true AND a.account_type IN ('income','expense') AND ($2::date IS NULL OR je.effective_date >= $2::date) AND ($3::date IS NULL OR je.effective_date <= $3::date) GROUP BY a.id ORDER BY a.account_type,a.code`,[req.auth!.companyId,parsed.data.from??null,parsed.data.to??null]);const rows=q.rows.map(r=>({...r,debit:Number(r.debit),credit:Number(r.credit),amount:Number(r.accountType==="income"?r.credit-r.debit:r.debit-r.credit)})),income=rows.filter(r=>r.accountType==="income").reduce((s,r)=>s+r.amount,0),expenses=rows.filter(r=>r.accountType==="expense").reduce((s,r)=>s+r.amount,0);return res.json({rows,income,expenses,netProfit:income-expenses,from:parsed.data.from??null,to:parsed.data.to??null});}catch(e){return next(e);}});
const loadingCreateSchema=z.object({invoiceId:z.string().uuid(),vehicleRegistration:z.string().trim().max(40).optional().default(""),driverName:z.string().trim().max(120).optional().default(""),driverPhone:z.string().trim().max(40).optional().default(""),destination:z.string().trim().max(500).optional().default("")});
